package com.fream.back.domain.m10.service.command;

import com.fream.back.domain.m16.entity.Xzj27;
import com.fream.back.domain.m16.service.query.Xzj27QueryService;
import com.fream.back.domain.m02.entity.Xdh20;
import com.fream.back.domain.m02.service.p14.Xdh20QueryService;
import com.fream.back.domain.m10.entity.Xtz73Status;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xzz58;
import com.fream.back.domain.m10.repository.Xzz58Repository;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m13.service.query.Xrd81QueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class Xzz58CommandService {

    private final Xzz58Repository saleBidRepository;
    private final Xrd81QueryService userQueryService;
    private final Xdh20QueryService productSizeQueryService;
    private final Xgg74CommandService saleCommandService;
    private final Xzj27QueryService orderBidQueryService;
    @Transactional
    public Xzz58 createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {

        Xrd81 seller = userQueryService.findByEmail(sellerEmail);


        Xdh20 productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));


        Xgg74 sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);


        Xzz58 saleBid = Xzz58.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(Xtz73Status.PENDING)
                .sale(sale)
                .build();


        saleBid = saleBidRepository.save(saleBid);


        sale.assignSaleBid(saleBid);


        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Xgg74 sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);

        Xzj27 orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));



        Xzz58 saleBid = Xzz58.builder()
                .seller(sale.getSeller())
                .productSize(sale.getProductSize())
                .bidPrice(orderBid.getBidPrice())
                .status(Xtz73Status.MATCHED)
                .sale(sale)
                .order(orderBid.getOrder())
                .build();


        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid);


        saleBidRepository.save(saleBid);


        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {

        Xzz58 saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));


        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }


        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }


        saleBidRepository.delete(saleBid);
    }
}
